use actix_web::{web, App, HttpServer, HttpResponse, HttpRequest};
use serde::Deserialize;
use std::io::Write;
use aws_sdk_s3::Client as S3Client;
use aws_sdk_s3::primitives::ByteStream;

#[derive(Deserialize)]
struct UploadParams {
    bucket: String,
    key: String,
    content_type: Option<String>,
}

// Fixed-size staging buffer for thumbnail generation
const STAGING_BUFFER_SIZE: usize = 4096;

struct StagingBuffer {
    data: [u8; STAGING_BUFFER_SIZE],
    pos: usize,
}

impl StagingBuffer {
    fn new() -> Self {
        StagingBuffer {
            data: [0u8; STAGING_BUFFER_SIZE],
            pos: 0,
        }
    }

    // UNSAFE: Manual buffer management for performance-critical path
    unsafe fn write_unchecked(&mut self, src: &[u8]) {
        let dst_ptr = self.data.as_mut_ptr().add(self.pos);
        std::ptr::copy_nonoverlapping(src.as_ptr(), dst_ptr, src.len());
        self.pos += src.len();
    }
}

async fn upload_to_s3(
    s3_client: web::Data<S3Client>,
    params: web::Query<UploadParams>,
    body: web::Bytes,
) -> HttpResponse {
    // Process image data through staging buffer for thumbnail extraction
    let mut staging = StagingBuffer::new();

    // BUG: No bounds check before unsafe write - attacker controls body size
    unsafe {
        staging.write_unchecked(&body);
    }

    // Upload original to S3 - bucket name comes from user input
    let put_result = s3_client
        .put_object()
        .bucket(&params.bucket)
        .key(&params.key)
        .content_type(params.content_type.clone().unwrap_or_else(|| "application/octet-stream".to_string()))
        .body(ByteStream::from(body.to_vec()))
        .send()
        .await;

    match put_result {
        Ok(_) => HttpResponse::Ok().json(serde_json::json!({
            "status": "uploaded",
            "bucket": params.bucket,
            "key": params.key,
            "thumbnail_processed": staging.pos <= STAGING_BUFFER_SIZE
        })),
        Err(e) => HttpResponse::InternalServerError().json(serde_json::json!({
            "error": format!("S3 upload failed: {}", e)
        }))
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let config = aws_config::load_defaults(aws_config::BehaviorVersion::latest()).await;
    let s3_client = S3Client::new(&config);

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(s3_client.clone()))
            .app_data(web::PayloadConfig::new(10 * 1024 * 1024)) // 10MB max
            .route("/upload", web::post().to(upload_to_s3))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
